package cn.zhuatech.energyai.controller; import cn.zhuatech.energyai.common.ApiResponse; import cn.zhuatech.energyai.dto.EnergyAiDto.*; import cn.zhuatech.energyai.service.EnergyAiService; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/admin") @PreAuthorize("hasAnyRole('DOMAIN_OPERATOR','QUALITY','ADMIN')") public class OperationsAdminController {private final EnergyAiService service;public OperationsAdminController(EnergyAiService service){this.service=service;}@GetMapping("/dashboard") public ApiResponse<Dashboard> dashboard(){return ApiResponse.ok(service.adminDashboard());}@GetMapping("/work-orders") public ApiResponse<List<WorkRecordView>> orders(){return ApiResponse.ok(service.workRecords());}}
